import{z as i,x as s,o as r,c as d,q as o,j as A,D as l,d as E,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const G=JSON.parse('{"title":"二次电子模糊模型","description":"","frontmatter":{"title":"二次电子模糊模型","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/secondary-electron-blur-model.md","filePath":"litho/secondary-electron-blur-model.md","lastUpdated":1791413859000}'),p={name:"litho/secondary-electron-blur-model.md"};function h(m,a,u,c,_,D){const t=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="二次电子模糊模型" tabindex="-1">二次电子模糊模型 <a class="header-anchor" href="#二次电子模糊模型" aria-label="Permalink to &quot;二次电子模糊模型&quot;">​</a></h1><div class="epigraph"><p>92 eV 的吸收不是一个点：级联二次电子把产酸事件涂成几纳米的核。这颗核不随 $\\lambda/\\mathrm{NA}$ 缩放。</p><footer>—— 据 Naulleau 对 EUV 二次电子模糊；Kozawa 对电离产酸路径的公开论述整理</footer></div><p><a href="/litho/acid-quencher-counting">上一课</a>把酸写成点计数。缺口是 EUV 上这些点并不钉在吸收位点：<a href="/litho/euv-secondary-electron">二次电子产额</a>已经说明产额与热化距离；本课把它收成可卷积的模糊模型，供平均场与后课 MC 共用。不要重推光学 PSF 或瑞利判据。Monte Carlo 如何抽样这颗核，留给<a href="/litho/stochastic-monte-carlo">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DUV 上 PAG 光解接近「光子在哪、酸在哪」（再加后课酸扩散）。EUV 上能量先变成光电子与级联，热化电子附着才产酸。空间上等价于：吸收剂量场卷积一颗电子核 \\(G_e(r)\\)，再进入 PAG 转化。Naulleau 把这颗核叫做二次电子模糊：它砍潜像 NILS，也决定上一课的有效体积。</p><p><span class="marginnote">术语翻译：二次电子就是「被入射光电子从原子或分子里撞出来的第 N 代电子」。一个 EUV 光子约 92 eV，自己只打出一两个光电子，但它们在胶里一路碰撞拉出一小群后代——真正产酸的是这群后代。</span></p><p>缺口不是再讲产额 \\(Y\\)，而是：工程模型用什么形状（高斯、指数、双高斯）、如何与酸扩散核 \\(G_a\\) 串联，以及为何 High-NA 缩小光学 PSF 之后这颗核仍在。</p><h3 id="两颗核不要并成一颗就忘账" tabindex="-1">两颗核不要并成一颗就忘账 <a class="header-anchor" href="#两颗核不要并成一颗就忘账" aria-label="Permalink to &quot;两颗核不要并成一颗就忘账&quot;">​</a></h3><p>紧凑模型常把 \\(G_e*G_a\\) 收成一颗有效高斯。换 PEB 主要动 \\(G_a\\)；换底层、换高 Z、换密度主要动 \\(G_e\\)。并成一颗之后，改烘箱会「看起来电子核也变了」。资格实验必须能拆。</p><p><span class="marginnote">不要把二次电子模糊写成全球 2 nm 常数。公开论述给的是纳米量级，随材料与密度变。本课钉可卷积的地位，不编射程表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>平均场：剂量 → 吸收 → \\(G_e\\) 卷积 → 平均酸 → \\(G_a\\)（PEB）→ \\(m\\) → 显影。随机：在吸收点抽样电子轨迹或直接从 \\(G_e\\) 抽产酸位置，再抽碱。量测：降 PEB 看高频 LER 是否还剩一块不随烘箱消失的地板——那块更像 \\(G_e\\) 与链尺寸。换 underlayer 看底部偏置与灵敏度，是界面电子，不是镜头离焦。</p><p><span class="marginnote">直觉类比：降 PEB 看 LER 地板，像把音响音量（酸扩散）关到最小还听得到的底噪——那才是电路（电子核）的本底。不随烘箱消失的高频毛刺，就是 \\(G_e\\) 的签名。</span></p><p>与<a href="/litho/euv-absorption-blur">吸收与模糊</a> 光学课序的拆法对齐：本课把同一语言接到胶模型，不重做薄膜光学。</p>',14)),(r(),A(n,null,{default:l(()=>[B(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%8D%E7%82%B9%22%5D%20--%3E%20GE%5B%22%E7%94%B5%E5%AD%90%E6%A0%B8%20Ge%22%5D%0A%20%20GE%20--%3E%20ACID%5B%22%E4%BA%A7%E9%85%B8%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20ACID%20--%3E%20GA%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%E6%A0%B8%20Ga%22%5D%0A%20%20GA%20--%3E%20M%5B%22%E8%84%B1%E4%BF%9D%E6%8A%A4%E5%9C%BA%22%5D%0A%20%20UL%5B%22%E5%BA%95%E5%B1%82%E7%81%8C%E7%94%B5%E5%AD%90%22%5D%20--%3E%20GE%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("一次吸收打出多个电子–空穴，电子在弹性/非弹性散射中降能，直至热化被 PAG 或陷阱捕获。核半径由热化距离与捕获截面决定。产额 \\(Y\\) 是积分结果：高 \\(Y\\) 往往伴随更远或更多的次级事件，灵敏度与模糊同向动——不是免费光子。"),e("a",{href:"/litho/euv-stochastics"},"随机效应"),E(" 已指出模糊既加偏置也减方差；本课指出执行它的是 \\(G_e\\)。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：把二次电子模糊当「光学分辨率的第 \\(k_1\\) 项」用 NA 去换算。它由热化距离和捕获截面决定，不随 \\(\\lambda/\\mathrm{NA}\\) 缩放——High-NA 把光学 PSF 磨得更尖，这颗几纳米的核纹丝不动。")],-1)),(r(),A(n,null,{default:l(()=>[B(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20PHOT%5B%22%E4%B8%80%E4%B8%AA%E5%85%89%E5%AD%90%E8%A2%AB%E5%90%B8%E6%94%B6%22%5D%20--%3E%20MULTI%5B%22%E6%89%93%E5%87%BA%E5%A4%9A%E4%B8%AA%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%22%5D%0A%20%20MULTI%20--%3E%20THERM%5B%22%E7%94%B5%E5%AD%90%E6%95%A3%E5%B0%84%E9%99%8D%E8%83%BD%E8%87%B3%E7%83%AD%E5%8C%96%22%5D%0A%20%20THERM%20--%3E%20CAP%5B%22%E8%A2%AB%20PAG%20%2F%20%E9%99%B7%E9%98%B1%E6%8D%95%E8%8E%B7%22%5D%0A%20%20CAP%20--%3E%20ACID%5B%22%E4%BA%A7%E9%85%B8%3A%20%E7%A6%BB%E5%90%B8%E6%94%B6%E7%82%B9%E5%87%A0%E7%BA%B3%E7%B1%B3%22%5D%0A%20%20HIY%5B%22%E4%BA%A7%E9%A2%9D%20Y%20%E8%B6%8A%E9%AB%98%22%5D%20--%3E%20MORE%5B%22%E6%AC%A1%E7%BA%A7%E4%BA%8B%E4%BB%B6%E6%9B%B4%E5%A4%9A%E6%9B%B4%E8%BF%9C%22%5D%0A%20%20MORE%20--%3E%20WIDE%5B%22%E7%94%B5%E5%AD%90%E6%A0%B8%E6%9B%B4%E5%AE%BD%3A%20%E6%A8%A1%E7%B3%8A%E6%9B%B4%E5%A4%A7%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>界面：底层电子向上注入，底部 \\(G_e\\) 不对称，footing。这是黏附课之外的电子几何，轮廓仿真要能加源项，而不是只加光学 \\(I(z)\\)。</p><p><span class="marginnote">金属氧化物没有长程 \\(G_a\\)，有效核更接近 \\(G_e\\) 与团簇尺寸。并核时不要把 CAR 的 PEB 高斯抄过去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写轨迹蒙特卡洛的截面数据库。不把 CXRO 计量工具上的核当成 NXE 胶规格。光子散粒仍在吸收位点抽样；电子核是条件分布。下一课把这两步写成可运行的 MC。</p><p>Flare 是远程光学台基，不要与 \\(G_e\\) 混。调焦补不了电子核。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 产酸位置 = 吸收位点卷积电子核 \\(G_e\\)，再卷积酸核 \\(G_a\\)。</li><li>核不随 NA 缩放；High-NA 光学更锐也砍不掉它。</li><li>改 PEB 与改底层必须能拆两颗核。</li><li>模糊同时降 NILS 与降计数方差。</li><li>出处：Naulleau 二次电子模糊；Kozawa 电离产酸；主干<a href="/litho/euv-secondary-electron">二次电子产额</a>。</li></ul>',7))])}const P=i(p,[["render",h]]);export{G as __pageData,P as default};
